import { createTianaFetch } from '@tianacloud/serverless';
let databaseReady = false;
let database;
let userId;
const stored = {};
function storageError(message) {
  let banner = document.getElementById('storage-error');
  if (!banner) { banner = document.createElement('div'); banner.id = 'storage-error'; banner.setAttribute('role', 'alert'); banner.style.cssText = 'padding:12px;background:#fff3cd;color:#633;position:sticky;top:0;z-index:9999'; document.body.prepend(banner); }
  banner.textContent = message;
}
async function sql(statement, args = []) {
  const response = await database.fetch(`${database.origin}/v3/pipeline`, {method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({requests:[{type:'execute',stmt:{sql:statement,args,want_rows:true}},{type:'close'}]})});
  if (!response.ok) throw new Error('Database response unavailable');
  const data = await response.json();
  const item = data.results?.[0];
  if (item?.type !== 'ok' || item.response?.type !== 'execute') throw new Error('Database statement failed or outcome unknown');
  return item.response.result;
}
try {
  const runtime = window.tiana;
  if (typeof runtime?.connection !== 'function' || typeof runtime?.auth?.getAccessToken !== 'function') throw new Error('Runtime unavailable');
  const sessionResponse = await fetch('./_tiana/session', {credentials:'same-origin', cache:'no-store'});
  if (!sessionResponse.ok) throw new Error('Session unavailable');
  const session = await sessionResponse.json();
  userId = session.user?.user_id;
  if (typeof userId !== 'string' || !userId) throw new Error('User identity unavailable');
  const connection = await runtime.connection();
  if (connection.sql_api !== 'hrana-v3') throw new Error('Unsupported SQL API');
  database = {origin:connection.origin, fetch:createTianaFetch({origin:connection.origin,auth:runtime.auth,requestBodyMode:'buffered'})};
  const result = await sql('SELECT key, value FROM schedule_settings WHERE user_id = ?', [{type:'text',value:userId}]);
  for (const row of result.rows || []) stored[row[0].value] = JSON.parse(row[1].value);
  databaseReady = true;
} catch (error) { storageError('云端数据暂不可用，当前更改不会保存。请检查连接后重新打开。'); }
let writeQueue = Promise.resolve();
function saveSetting(key, value) {
  if (!databaseReady) return;
  const encoded = JSON.stringify(value);
  writeQueue = writeQueue.then(async () => {
    if (!databaseReady) return;
    try { await sql('INSERT INTO schedule_settings (user_id,key,value) VALUES (?,?,?) ON CONFLICT(user_id,key) DO UPDATE SET value=excluded.value', [{type:'text',value:userId},{type:'text',value:key},{type:'text',value:encoded}]); }
    catch (error) { databaseReady = false; storageError('保存结果未确认。请重新打开并核对数据后再修改。'); }
  });
}
