const BUILD_ID = '2026-10-22 07:25';

/* ---------- 刷新 / 检查更新：解决"改了数据客户端还看旧版" ---------- */
const UPDATE_CHECK_MS = 15 * 60 * 1000;   // 后台每 15 分钟静默查一次

function rfToast(msg, ms){
  let el = document.getElementById('rfToast');
  if(!el){ el = document.createElement('div'); el.id = 'rfToast'; document.body.appendChild(el); }
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(el._t);
  el._t = setTimeout(function(){ el.classList.remove('show'); }, ms || 2400);
}
/* 强制重新拉取入口页：加随机参数绕过浏览器/CDN/Service Worker 三层缓存 */
function forceReload(){
  try{
    const u = new URL(location.href);
    u.searchParams.set('v', Date.now().toString(36));
    location.replace(u.toString());
  }catch(e){
    location.reload();
  }
}
function updateEntryUrl(){
  if(!/^https?:$/.test(location.protocol)) return null;   // 本地文件打开，无从比较
  return location.pathname.replace(/[^/]*$/, '') + 'index.html';
}
async function checkUpdate(manual){
  const entry = updateEntryUrl();
  if(!entry){ if(manual) rfToast('本地文件打开，内容就是本机的'); return; }
  const btn = document.getElementById('rfBtn');
  if(btn) btn.classList.add('busy');
  try{
    const r = await fetch(entry + '?ck=' + Date.now(), {cache:'no-store'});
    if(!r.ok) throw new Error('HTTP ' + r.status);
    const txt = await r.text();
    const m = txt.match(/const BUILD_ID = '([^']*)'/);
    const remote = m ? m[1] : '';
    if(remote && remote !== BUILD_ID){
      if(manual){ forceReload(); return; }        // 点了刷新且确有新版 → 直接换新
      const bar = document.getElementById('updateBar');
      const ver = document.getElementById('ubVer');
      if(ver) ver.textContent = '线上版本 ' + remote + ' · 你正在看 ' + BUILD_ID;
      if(bar) bar.classList.add('show');
    }else if(manual){
      rfToast('已是最新版本 · ' + BUILD_ID);
    }
  }catch(e){
    if(manual) rfToast('检查更新失败，请确认已联网后重试');
  }finally{
    if(btn) btn.classList.remove('busy');
  }
}
function manualRefresh(){ location.reload(); }

window.addEventListener('load', function(){ setTimeout(function(){ checkUpdate(false); }, 5000); });
document.addEventListener('visibilitychange', function(){
  if(document.visibilityState === 'visible') checkUpdate(false);
});
setInterval(function(){ checkUpdate(false); }, UPDATE_CHECK_MS);


/* ---------- 教师身份（我是谁）+ 个人课表数据 ---------- */
let WHO = typeof stored.who === 'string' ? stored.who : '';
// 全部教师（授课教师 + 班主任），按拼音排序
const TEACHERS = (function(){
  const set = new Set();
  DATA.classes.forEach(c=>{
    ['single','double'].forEach(k=>{
      DATA.periods.forEach(p=>{
        (c[k][p.key]||[]).forEach(cell=>{ if(cell && cell.t) set.add(cell.t); });
      });
    });
    if(c.banzhuren) set.add(c.banzhuren);
  });
  return [...set].sort((a,b)=>a.localeCompare(b,'zh-Hans-CN-u-co-pinyin'));
})();
// 教师 -> 单/双周 -> 节次 -> [周一..周五] = {cls, course}
const TEACH_MAP = (function(){
  const m = {};
  DATA.classes.forEach(c=>{
    ['single','double'].forEach(k=>{
      DATA.periods.forEach(p=>{
        (c[k][p.key]||[]).forEach((cell,di)=>{
          if(cell && cell.t){
            const byK = (m[cell.t] = m[cell.t] || {single:{}, double:{}});
            const byP = (byK[k][p.key] = byK[k][p.key] || []);
            byP[di] = {cls:c.name, course:cell.c};
          }
        });
      });
    });
  });
  return m;
})();
// 是否为"我"（当前所选教师）的课
function isMyCourse(cell){ return !!WHO && !!cell && cell.t===WHO; }
// 取某教师某单双周、某节次、某天的授课记录（dayIdx 0=周一）
function teacherAt(name, kind, periodKey, dayIdx){
  const m = TEACH_MAP[name]; if(!m) return null;
  const byP = m[kind] && m[kind][periodKey]; if(!byP) return null;
  return byP[dayIdx] || null;
}

