function setMotivate(){
  const d = new Date().getDay();      // 0日..6六
  const idx = (d+6)%7;                // 周一=0..周五=4，周末=5/6
  const q = MOTIVATE[idx % MOTIVATE.length];
  const el = document.getElementById('motivate');
  if(el) el.textContent = q;
}

