/* ---------- 状态 ---------- */
const state = {
  kind:'auto',            // auto | single | double
  tabIndex:0,             // 当前选中班级索引
  view:'class',           // class=班级课表 | mine=我的（教师个人）课表
  pickDay:null,           // 班级课表手动查看的星期：null=跟随今天 | 1..5（周一~周五）
  dutyView:'week',        // week | day
  dutyWeek:null,          // null=自动定位当前周
  weekSel:null,           // 手动指定周次：null=自动 | 1..20（同时驱动值周与单双周）
  dismissed:false,        // 本次已关闭提醒横幅
  remindedKey:'',         // 已提醒的课（防重复）
  classCollapsed:{}       // 各年级是否折叠：{'七年级':true,...}
};
// "我的班"索引 / 年级：优先取我当班主任的班，否则取我任课最多的班；都没有则 -1 / null
let myIdx = -1, myGrade = null;
function recomputeMy(){
  if(!WHO){ myIdx = -1; myGrade = null; return; }
  let idx = DATA.classes.findIndex(c=>c.banzhuren===WHO);
  if(idx<0){   // 非班主任：取我任课最多的班
    const cnt = {};
    DATA.classes.forEach((c,i)=>{
      ['single','double'].forEach(k=>{
        DATA.periods.forEach(p=>{
          (c[k][p.key]||[]).forEach(cell=>{ if(cell && cell.t===WHO) cnt[i]=(cnt[i]||0)+1; });
        });
      });
    });
    let best=-1, bestN=0;
    Object.keys(cnt).forEach(i=>{ if(cnt[i]>bestN){ bestN=cnt[i]; best=Number(i); } });
    idx = bestN>0 ? best : -1;
  }
  myIdx = idx;
  myGrade = myIdx>=0 ? DATA.classes[myIdx].name.slice(0,3) : null;
}
recomputeMy();

/* ---------- 我是谁：设置与同步 ---------- */
