/* ---------- 工具 ---------- */
const pad = n => String(n).padStart(2,'0');
function hm2min(hm){const [h,m]=hm.split(':').map(Number);return h*60+m;}
function semStart(){const [y,m,d]=SEM_START.split('-').map(Number);return new Date(y,m-1,d);}
function weekInfo(now){
  const s = semStart(); s.setHours(0,0,0,0);
  const t = new Date(now); t.setHours(0,0,0,0);
  const diffDays = Math.floor((t - s)/86400000);
  const week = Math.floor(diffDays/7)+1;
  const kind = (week%2===1)?'single':'double';
  return {week, kind, inSemester: diffDays>=0};
}
/* 当前生效的周次：优先取手动指定，否则按日期计算 */
function currentWeekNo(now){
  if(state.weekSel) return state.weekSel;
  return weekInfo(now).week;
}
function effectiveKind(now){
  if(state.kind!=='auto') return state.kind;
  if(state.weekSel) return (state.weekSel%2===1)?'single':'double';
  return weekInfo(now).kind;
}
function periodRowByKey(key){return DATA.periods.find(p=>p.key===key);}
function nowMinutes(now){return now.getHours()*60+now.getMinutes()+now.getSeconds()/60;}
function slotTimes(slot, isMonday){
  return {s: isMonday&&slot.monS?slot.monS:slot.s, e: isMonday&&slot.monE?slot.monE:slot.e};
}
function findCurrentSlot(now){
  const nm = nowMinutes(now); const isMonday = now.getDay()===1;
  for(const slot of TIMETABLE){
    const {s,e} = slotTimes(slot,isMonday);
    if(nm>=hm2min(s) && nm<hm2min(e)) return {...slot, _s:s, _e:e};
  }
  return null;
}
function findNextSlot(now){
  const nm = nowMinutes(now); const isMonday = now.getDay()===1;
  for(const slot of TIMETABLE){
    const {s} = slotTimes(slot,isMonday);
    if(hm2min(s)>nm) return {...slot, _s:s, _e:slotTimes(slot,isMonday).e};
  }
  return null;
}

/* ---------- 时钟与状态刷新 ---------- */
function tickClock(){
  const now = new Date();
  document.getElementById('clock').textContent =
    `${DAY_NAMES[now.getDay()]} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
}

function refreshStatus(){
  const now = new Date();
  const wi = weekInfo(now);
  const kind = effectiveKindForDate(now);
  const todayCol = effectiveDayCol(now);
  const ov = getAdjust(dateStrOf(now));

  // 顶栏徽章
  if(state.weekSel){
    document.getElementById('weekBadge').textContent = `第 ${state.weekSel} 周`;
    document.getElementById('weekBadge').classList.add('adj');
    document.getElementById('weekBadge').title = '已手动指定周次';
  }else{
    document.getElementById('weekBadge').textContent = wi.inSemester?`第 ${wi.week} 周`:'未开学';
    document.getElementById('weekBadge').classList.remove('adj');
    document.getElementById('weekBadge').title = '';
  }
  document.getElementById('kindBadge').textContent = kind==='single'?'单周课表':'双周课表';
  const adjBadge = document.getElementById('adjustBadge');
  if(ov){
    adjBadge.style.display='';
    adjBadge.textContent = '调休调整' + (ov.note?(' · '+ov.note):'');
  }else{
    adjBadge.style.display='none';
  }
  document.getElementById('dateBadge').textContent =
    `${now.getFullYear()}年${now.getMonth()+1}月${now.getDate()}日 · ${DAY_NAMES[now.getDay()]}` +
    (ov?` → 按${DAY_NAMES[todayCol]}课`:'');
  setMotivate();

  // 当前时段
  const cur = findCurrentSlot(now);
  const nxt = findNextSlot(now);
  const nowEl = document.getElementById('nowSlot');
  const nextEl = document.getElementById('nextSlot');
  if(cur){
    nowEl.textContent = cur.name;
    nextEl.textContent = cur.note ? cur.note : (nxt?`下一时段：${nxt.name} ${nxt._s}`:'今天时段已结束');
  }else{
    nowEl.textContent = '休息时间';
    nextEl.textContent = nxt?`下一时段：${nxt.name} ${nxt._s}${nxt.note?'（'+nxt.note+'）':''}`:'';
  }
  renderDaySwitch(todayCol);
  renderTable(cur, todayCol, kind, now);
  renderMineTable(cur, todayCol, kind, now);
  checkRemind(now, cur, kind, todayCol);
}

/* ---------- 选项卡（按年级分组、可折叠） ---------- */
function allGradeNames(){ return [...new Set(DATA.classes.map(c=>c.name.slice(0,3)))]; }
function defaultOpenGrade(){
  if(myGrade) return myGrade;
  const c = DATA.classes[state.tabIndex];
  return c ? c.name.slice(0,3) : '九年级';
}
function isGradeCollapsed(g){
  return state.classCollapsed[g]!==undefined ? state.classCollapsed[g] : (g!==defaultOpenGrade());
}
function renderTabs(){
  const box = document.getElementById('classItems');
  box.innerHTML = '';

  const groups = {};
  DATA.classes.forEach((c,i)=>{
    const g = c.name.slice(0,3);
    (groups[g]=groups[g]||[]).push({c,i});
  });
  Object.keys(groups).forEach(g=>{
    const collapsed = isGradeCollapsed(g);
    const gh = document.createElement('div');
    gh.className = 'cl-group-head'+(collapsed?' collapsed':'');
    gh.innerHTML = `<span class="arr">▾</span>${g}<span class="cnt">(${groups[g].length})</span>`;
    gh.onclick = ()=>{ state.classCollapsed[g] = !collapsed; renderTabs(); };
    box.appendChild(gh);
    const body = document.createElement('div');
    body.className = 'cl-group-body';
    groups[g].forEach(({c,i})=>{
      const d = document.createElement('div');
      d.className = 'class-item'+(state.view==='class'&&i===state.tabIndex?' active':'')+(i===myIdx?' mine':'');
      d.innerHTML = `<div class="ci-name">${c.name}${i===myIdx?' <span class="star">★</span>':''}</div><div class="ci-room">${c.room} · ${c.banzhuren}</div>`;
      d.onclick = ()=>{state.view='class'; state.tabIndex=i; renderTabs(); const n=new Date(); renderTable(findCurrentSlot(n), effectiveDayCol(n), effectiveKindForDate(n), n);};
      body.appendChild(d);
    });
    box.appendChild(body);
  });
  syncClassToggleBtn();
}
function syncClassToggleBtn(){
  const btn = document.querySelector('.cl-toggle');
  if(!btn) return;
  const grades = allGradeNames();
  const allExpanded = grades.length>0 && grades.every(g=>!isGradeCollapsed(g));
  btn.textContent = allExpanded ? '折叠' : '展开';
}
function toggleAllClasses(){
  const grades = allGradeNames();
  const allExpanded = grades.length>0 && grades.every(g=>!isGradeCollapsed(g));
  const target = allExpanded; // 全展开→折叠(true)；否则→展开(false)
  grades.forEach(g=>state.classCollapsed[g]=target);
  renderTabs();
}
function jumpMine(){
  const el = document.getElementById('mineBlock');
  if(el) el.scrollIntoView({behavior:'smooth', block:'center'});
  if(!WHO){ const s=document.getElementById('whoSel'); if(s) s.focus(); }
}

/* ---------- 班级课表：星期切换（查看其他天的课，便于调课） ---------- */
function renderDaySwitch(todayCol){
  const box = document.getElementById('daySwitch');
  if(!box) return;
  const today = (todayCol>=1 && todayCol<=5) ? todayCol : -1;
  const sel = state.pickDay;
  const names = ['一','二','三','四','五'];
  box.innerHTML = [1,2,3,4,5].map(d=>{
    const on = sel ? (sel===d) : (d===today);
    return `<button class="${on?'on':''}${d===today?' is-today':''}" data-click="setPickDay(${d})" title="查看周${names[d-1]}的课表">周${names[d-1]}</button>`;
  }).join('');
}
function setPickDay(d){
  state.pickDay = (state.pickDay === d) ? null : d;   // 再点一次 = 回到今天
  refreshStatus();
}

/* ---------- 课表表格（仅显示当天） ---------- */
function renderTable(cur, todayCol, kind, now){
  const cls = DATA.classes[state.tabIndex];
  const weekData = kind==='single' ? cls.single : cls.double;
  const todayReal = todayCol;                    // 今天实际上的星期（课表口径）
  const viewCol = state.pickDay || todayCol;     // 正在查看的星期（可手动选）
  const isToday = viewCol === todayReal;
  const isWeekend = viewCol<1 || viewCol>5;
  const ov = getAdjust(dateStrOf(now));
  const isAdjustDay = !!(ov && ov.day && ov.day!=='auto');

  document.getElementById('schTitle').textContent =
    cls.name + (isToday && isAdjustDay ? '（调休）' : '');

  if(isWeekend){
    document.getElementById('tt').innerHTML =
      `<tbody><tr><td style="padding:34px 12px;text-align:center;color:var(--muted);line-height:1.9">今天是周末，不显示课表。<br><span style="font-size:12px">点右上角「周一~周五」可以查看任意一天的课表。</span></td></tr></tbody>`;
    return;
  }
  const dayIdx = viewCol-1;
  const tag = isToday
    ? `<span class="th-today${isAdjustDay?' adj':''}">${isAdjustDay?'调休·今天':'今天'}</span>`
    : `<span class="th-today pick">查看</span>`;

  let html = `<thead><tr><th>节次 / 时间</th><th class="today">${DAY_NAMES[viewCol]}${tag}</th></tr></thead><tbody>`;
  const nxt = findNextSlot(now);
  DATA.periods.forEach((p)=>{
    const slot = TIMETABLE.find(t=>t.period===p.key);
    const {s,e} = slotTimes(slot, viewCol===1);
    const isActiveRow = isToday && cur && cur.period===p.key;
    const isNextRow = isToday && !cur && !isWeekend && nxt && nxt.period===p.key;
    const cell = weekData[p.key][dayIdx];
    const isCurrent = isActiveRow && !isWeekend;
    const isNext = isNextRow;
    const isMine = isMyCourse(cell);
    html += `<tr class="${isActiveRow?'now-row':''}${isNextRow?' next-row':''}">`;
    html += `<th>${p.name}<span class="tm">${s}-${e}</span></th>`;
    const badge = isCurrent ? '<span class="badge-now">上课中</span>' : (isNext ? '<span class="badge-next">即将上课</span>' : '');
    /* 晨会 / 晚自习在源表里只有教师姓名，没有课程名称 → 只显示教师名 */
    const cellBody = cell.c ? (cell.c + `<span class="teacher">${cell.t||''}</span>`)
                            : (cell.t ? `<span class="solo">${cell.t}</span>` : '—');
    html += `<td class="${isCurrent?'current':''}${isNext?'next':''}${isMine?' mine-cell':''}">${badge}${cellBody}</td>`;
    html += '</tr>';
  });
  html += '</tbody>';
  document.getElementById('tt').innerHTML = html;
}

/* ---------- 个人课表（我是谁）：独立卡片，与班级课表同时显示 ---------- */
function renderMineTable(cur, todayCol, kind, now){
  const tt = document.getElementById('ttMine');
  const titleEl = document.getElementById('schTitleMine');
  const tagEl = document.getElementById('mineWhoTag');
  if(!tt || !titleEl) return;
  if(tagEl) tagEl.textContent = WHO || '';
  if(!WHO){
    titleEl.textContent = '我的课表';
    tt.innerHTML = '<tbody><tr><td style="padding:26px 12px;text-align:center;color:var(--muted);line-height:1.95">还没设置「我是谁」<br><span style="font-size:12px">在上方「我是谁」里选一次名字，这里就显示你的个人课表，并自动记住。</span></td></tr></tbody>';
    return;
  }
  const isWeekend = todayCol<1 || todayCol>5;
  const ov = getAdjust(dateStrOf(now));
  const isAdjustDay = !!(ov && ov.day && ov.day!=='auto');
  titleEl.textContent = DAY_NAMES[todayCol] + '我的课表' + (isAdjustDay?'（调休）':'');
  if(isWeekend){
    tt.innerHTML =
      `<tbody><tr><td style="padding:34px 12px;text-align:center;color:var(--muted);line-height:1.9">今天是周末，不显示课表。<br><span style="font-size:12px">如需查看，可在上方「手动调整」里指定显示的星期。</span></td></tr></tbody>`;
    return;
  }
  const dayIdx = todayCol-1;
  const tag = `<span class="th-today${isAdjustDay?' adj':''}">${isAdjustDay?'调休·今天':'今天'}</span>`;
  const nxt = findNextSlot(now);
  let html = `<thead><tr><th>节次 / 时间</th><th class="today">${DAY_NAMES[todayCol]}${tag}</th></tr></thead><tbody>`;
  DATA.periods.forEach((p)=>{
    const slot = TIMETABLE.find(t=>t.period===p.key);
    const {s,e} = slotTimes(slot, todayCol===1);
    const rec = teacherAt(WHO, kind, p.key, dayIdx);
    const hasCls = !!rec;
    const isCurrent = hasCls && cur && cur.period===p.key;
    const isNext = hasCls && !cur && nxt && nxt.period===p.key;
    html += `<tr class="${isCurrent?'now-row':''}${isNext?' next-row':''}">`;
    html += `<th>${p.name}<span class="tm">${s}-${e}</span></th>`;
    const content = hasCls
      ? (rec.course ? `${rec.course}<span class="teacher">${rec.cls}</span>` : `<span class="solo">${rec.cls}</span>`)
      : '<span class="free">空堂</span>';
    const badge = isCurrent ? '<span class="badge-now">上课中</span>' : (isNext ? '<span class="badge-next">即将上课</span>' : '');
    html += `<td class="${isCurrent?'current':''}${isNext?'next':''}">${badge}${content}</td>`;
    html += '</tr>';
  });
  html += '</tbody>';
  tt.innerHTML = html;
}

