/* ---------- 提醒：下节课是我的课，提前10分钟 ---------- */
let remindOsc = null;
function checkRemind(now, cur, kind, todayCol){
  const banner = document.getElementById('remindBanner');
  if(!WHO || todayCol<1||todayCol>5){ banner.style.display='none'; return; }
  // 找今天的课程时段中，下一个"我的课"
  const nm = nowMinutes(now);
  const isMonday = now.getDay()===1;
  let target = null;
  for(const slot of TIMETABLE){
    if(!slot.period) continue;
    const {s} = slotTimes(slot,isMonday);
    if(hm2min(s) > nm){
      const rec = teacherAt(WHO, kind, slot.period, todayCol-1);
      if(rec){ target = {...slot, _s:s, course:rec.course, cls:rec.cls}; }
      break; // 只看下一节课
    }
  }
  if(!target || state.dismissed){ banner.style.display='none'; return; }
  const minsLeft = hm2min(target._s) - nm;
  const row = periodRowByKey(target.period);
  const key = `${now.toDateString()}-${kind}-${target.period}`;
  if(minsLeft<=10 && minsLeft>0){
    banner.style.display='block';
    document.getElementById('remindText').textContent =
      `下节课是您的课：${target.cls} ${target.course}（${row?row.name:''} ${target._s} 上课），还有 ${Math.ceil(minsLeft)} 分钟！`;
    if(state.remindedKey!==key){
      state.remindedKey = key;
      playRemindSound();
      if(window.Notification && Notification.permission==='granted'){
        new Notification('上课提醒', {body:`${target.cls} ${target.course} ${target._s} 上课，还有 ${Math.ceil(minsLeft)} 分钟`});
      }
    }
  }else{
    banner.style.display='none';
  }
}
function playRemindSound(){
  try{
    const ctx = new (window.AudioContext||window.webkitAudioContext)();
    remindOsc = ctx;
    const beep = (t,dur)=>{ const o=ctx.createOscillator(), g=ctx.createGain();
      o.connect(g); g.connect(ctx.destination); o.type='sine'; o.frequency.value=880;
      g.gain.setValueAtTime(.25,ctx.currentTime+t); g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+t+dur);
      o.start(ctx.currentTime+t); o.stop(ctx.currentTime+t+dur); };
    beep(0,.3); beep(.5,.3); beep(1,.5);
  }catch(e){}
}
function stopRemindSound(){ if(remindOsc){try{remindOsc.close()}catch(e){} remindOsc=null;} }
function dismissRemind(){ state.dismissed=true; document.getElementById('remindBanner').style.display='none'; }
function enableNotify(){
  const btn = document.getElementById('notifBtn');
  if(!window.Notification){ btn.textContent='⚠ 浏览器不支持通知'; return; }
  Notification.requestPermission().then(p=>{
    if(p==='granted'){ btn.textContent='✅ 提醒已开启'; btn.classList.add('on');
      new Notification('提醒已开启',{body:'下节课前10分钟提醒您'}); }
    else btn.textContent='⚠ 通知被拒绝（页面横幅仍会提醒）';
  });
}

/* ---------- 值周 ---------- */
/* 食堂值日按"星期几"取（跟随当天实际所上的课）；周末无（回退到周一，仅在无课表时用） */
function cafeteriaForDay(dow){
  const d = (dow>=1 && dow<=5) ? dow : 1;
  return CAFETERIA[d] || CAFETERIA[1];
}
function renderDuty(){
  const now = new Date();
  const w = state.dutyWeek || Math.min(Math.max(dutyWeekFor(now),1),20);
  document.getElementById('dutyWkLabel').textContent = `第${w}周`;
  document.getElementById('dutyWkLabel2').textContent = `第${w}周`;
  const d = DUTY.find(x=>x.w===w);
  const bd = BD_DUTY.find(x=>x.w===w);
  const dow = effectiveDayCol(now);          // 已按调休换算的"今天上星期几"
  const caf = cafeteriaForDay(dow);          // 食堂值日跟随"今天上星期几"

  const box = document.getElementById('dutyItems');
  let items = [];
  if(state.dutyView==='week'){
    items = [
      {role:'行政值周', name:d.a},
      {role:'中学部值周', name:d.m, hl:true},
      {role:'课间操', name:d.c},
      {role:'晚操', name:d.g}
    ];
  }else{
    if(dow<1||dow>5){
      items = [{role:'今天周末', name:'本表仅周一至周五'}];
    }else{
      items = [
        {role:'中学部值周（全天）', name:d.m, hl:true},
        {role:'今天课间操值班', name:d.c},
        {role:'今天晚操值班', name:d.g},
        {role:'今天班主任值周领导', name:bd.l}
      ];
    }
  }
  // 食堂值日：始终按"今天上星期几"显示（按周视图也同样展示当天应值人员）
  CAFETERIA_POSTS.forEach((p,i)=>items.push({role:'食堂值日 · '+p, name:caf.people[i]}));
  const meTag = (name)=> (WHO && name===WHO) ? ' <span class="me-tag">我</span>' : '';
  const isMe = (name)=> !!WHO && name===WHO;
  box.innerHTML = items.map(it=>
    `<div class="duty-item${(it.hl||isMe(it.name))?' hl':''}"><div class="di-role">${it.role}</div><div class="di-name">${it.name}${meTag(it.name)}</div></div>`
  ).join('');

  const box2 = document.getElementById('bdDutyItems');
  box2.innerHTML =
    `<div class="duty-item${isMe(bd.l)?' hl':''}"><div class="di-role">值周领导</div><div class="di-name">${bd.l}${meTag(bd.l)}</div></div>` +
    bd.t.map(t=>`<div class="duty-item${isMe(t)?' hl':''}"><div class="di-role">值周班主任</div><div class="di-name">${t}${meTag(t)}</div></div>`).join('');
}
function dutyWeekMove(d){
  const cur = state.dutyWeek || Math.min(Math.max(dutyWeekFor(new Date()),1),20);
  let w = cur + d; if(w<1)w=20; if(w>20)w=1;
  state.dutyWeek = w;
  // 用箭头翻周时，同步"指定周次"与单双周（保持三处一致）
  state.weekSel = w;
  saveSetting('weekSel', state.weekSel);
  syncWeekSelUI();
  if(state.kind==='auto') refreshStatus();
  renderDuty();
}
function setDutyView(v){
  state.dutyView = v;
  document.querySelectorAll('.view-switch button').forEach(b=>b.classList.toggle('on',b.dataset.v===v));
  renderDuty();
}

/* ---------- 单双周切换 ---------- */
function setKind(k){
  state.kind = k;
  document.querySelectorAll('.week-kind-switch button').forEach(b=>b.classList.toggle('on',b.dataset.k===k));
  const hint = document.getElementById('weekHint');
  if(hint){
    if(state.weekSel){
      const auto = (state.weekSel%2===1)?'单周':'双周';
      hint.textContent = k==='auto'
        ? `已指定第${state.weekSel}周（${auto}）· 值周同步`
        : `已指定第${state.weekSel}周 · 课表强制${k==='single'?'单':'双'}周`;
      hint.style.color = 'var(--amber)';
    }
  }
  refreshStatus();
}
/* ---------- 手动指定周次（值周 + 单双周 联动） ---------- */
function buildWeekOptions(){
  const sel = document.getElementById('weekSel');
  let opts = '<option value="">自动</option>';
  for(let i=1;i<=20;i++) opts += `<option value="${i}">第${i}周</option>`;
  sel.innerHTML = opts;
}
function setWeekSel(v){
  const n = v ? Number(v) : null;
  state.weekSel = (n && n>=1 && n<=20) ? n : null;
  // 指定周次时，若单双周处于"自动"，则跟随该周次奇偶；同时清掉值周的临时翻页
  state.dutyWeek = null;
  if(state.weekSel && state.kind==='auto'){
    // 让 refreshStatus 按 weekSel 推导单双周（effectiveKind 已处理）
  }
  saveSetting('weekSel', state.weekSel);
  syncWeekSelUI();
  refreshStatus();
  renderDuty();
}
function syncWeekSelUI(){
  const sel = document.getElementById('weekSel');
  if(!sel) return;
  sel.value = state.weekSel ? String(state.weekSel) : '';
  sel.classList.toggle('pinned', !!state.weekSel);
  const hint = document.getElementById('weekHint');
  if(hint){
    hint.textContent = state.weekSel
      ? `已指定第${state.weekSel}周（${state.weekSel%2===1?'单周':'双周'}）· 值周同步`
      : '默认自动按日期计算';
    hint.style.color = state.weekSel ? 'var(--amber)' : '';
  }
  // 指定周次时，单双周按钮的"自动"高亮仍需正确反映
  if(state.weekSel && state.kind==='auto'){
    document.querySelectorAll('.week-kind-switch button').forEach(b=>b.classList.toggle('on', b.dataset.k==='auto'));
  }
}
function loadWeekSel(){ if (stored.weekSel >= 1 && stored.weekSel <= 20) state.weekSel = stored.weekSel; }

/* ---------- 手动调整（节假日调休） ---------- */
let ADJ = {};
function loadAdjust(){ ADJ = stored.adjustments && typeof stored.adjustments === 'object' ? stored.adjustments : {}; }
function persistAdjust(){ saveSetting('adjustments', ADJ); }
function getAdjust(ds){ return ADJ[ds]||null; }
function dateStrOf(now){ return `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`; }
function effectiveKindForDate(now){
  const ov = getAdjust(dateStrOf(now));
  if(ov && ov.kind && ov.kind!=='auto') return ov.kind;
  return effectiveKind(now);
}
function effectiveDayCol(now){
  const ov = getAdjust(dateStrOf(now));
  if(ov && ov.day && ov.day!=='auto') return Number(ov.day);
  return now.getDay();
}
/* 调休/手动调整时，值周值日所应对应的"周次"。
   规则：若有手动指定单双周，则取与"调整后单双周"一致、且离该日历日期最近的周次；
   例如 9/20(周日，日历第3周/单周) 手动改为上"双周五"的课 → 值周按第4周。
   若只是指定了"上周几的课"而未改单双周，则周次仍按日历周。 */
function dutyWeekFor(now){
  // 用户手动指定了周次 → 直接以此为准（同时值周与单双周都跟着走）
  if(state.weekSel) return Math.min(Math.max(state.weekSel,1),20);
  const wi = weekInfo(now);
  const ov = getAdjust(dateStrOf(now));
  if(!ov) return wi.week;
  const kindWanted = (ov.kind && ov.kind!=='auto') ? ov.kind : wi.kind;
  const wantSingle = kindWanted==='single';
  // 日历周次本身就是目标单双周 → 直接用
  if((wi.week%2===1)===wantSingle) return wi.week;
  // 否则取相邻的、奇偶性匹配的周（优先"下一周"，因为在同周内调整通常指向即将到来的那一周）
  let w = wi.week;
  if(ov.kind && ov.kind!=='auto'){
    // 指定了单双周 → 找最近的匹配周次（优先向后）
    if(((w+1)%2===1)===wantSingle) return w+1;
    if(((w-1)%2===1)===wantSingle) return w-1;
  }
  return w;
}
function escapeHtml(s){ return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
function renderAdjustList(){
  const box = document.getElementById('adjustList');
  const keys = Object.keys(ADJ).sort();
  if(keys.length===0){
    box.innerHTML = '<div class="adjust-empty">暂无手动调整。遇到调休补班时，在这里选日期、指定当天上单/双周、上周几的课，点“保存调整”即可，下次打开自动生效。</div>';
    return;
  }
  box.innerHTML = keys.map(k=>{
    const o = ADJ[k];
    const kindTxt = o.kind==='auto'?'自动':(o.kind==='single'?'单周':'双周');
    const dayTxt = o.day==='auto'?'实际星期':DAY_NAMES[Number(o.day)];
    return `<div class="adjust-row">
      <span class="ar-date">${k}</span>
      <span class="ar-tag">${kindTxt}</span>
      <span class="ar-tag">${dayTxt}课</span>
      <span class="ar-note">${o.note?('· '+escapeHtml(o.note)):''}</span>
      <button class="ar-del" data-click="editAdjust('${k}')">编辑</button>
      <button class="ar-del" data-click="deleteAdjust('${k}')">删除</button>
    </div>`;
  }).join('');
}
function saveAdjust(){
  const k = document.getElementById('adjDate').value;
  if(!k){ alert('请先选择日期'); return; }
  ADJ[k] = {
    kind: document.getElementById('adjKind').value,
    day:  document.getElementById('adjDay').value,
    note: document.getElementById('adjNote').value.trim()
  };
  persistAdjust(); renderAdjustList(); refreshStatus(); renderDuty();
}
function editAdjust(k){
  const o = ADJ[k]; if(!o) return;
  document.getElementById('adjDate').value = k;
  document.getElementById('adjKind').value = o.kind||'auto';
  document.getElementById('adjDay').value  = o.day||'auto';
  document.getElementById('adjNote').value = o.note||'';
}
function deleteAdjust(k){ delete ADJ[k]; persistAdjust(); renderAdjustList(); refreshStatus(); renderDuty(); }
function onAdjDateChange(){
  const k = document.getElementById('adjDate').value;
  const o = ADJ[k];
  document.getElementById('adjKind').value = o?o.kind:'auto';
  document.getElementById('adjDay').value  = o?o.day:'auto';
  document.getElementById('adjNote').value = o?o.note:'';
}

