Object.assign(window, {manualRefresh,forceReload,openInstall,closeInstall,enableNotify,dismissRemind,stopRemindSound,setWho,setWeekSel,setKind,dutyWeekMove,setDutyView,saveAdjust,toggleAllClasses,setPickDay,editAdjust,deleteAdjust,doInstall,copyLink,downloadShortcut});

function dispatchAction(event, attr) {
  const el = event.target.closest('['+attr+']');
  if (!el) return;
  const action = el.getAttribute(attr);
  if (action === 'if(event.target===this)closeInstall()') { if (event.target === el) closeInstall(); return; }
  const match = /^(\w+)\((.*?)\)$/.exec(action);
  if (!match || typeof window[match[1]] !== 'function') return;
  const arg = match[2];
  if (!arg) window[match[1]]();
  else if (arg === 'this.value') window[match[1]](el.value);
  else if (arg === 'this') window[match[1]](el);
  else if (/^-?\d+$/.test(arg)) window[match[1]](Number(arg));
  else if (/^'[^']*'$/.test(arg)) window[match[1]](arg.slice(1,-1));
}
document.addEventListener('click', event => dispatchAction(event, 'data-click'));
document.addEventListener('change', event => dispatchAction(event, 'data-change'));
